/**
 * invoice-pdf.js — High-Precision Text & Vector A4 Invoice PDF Generator
 * 
 * Generates genuine text/vector-based PDF documents using jsPDF.
 * - 100% vector lines, boxes, borders, and fills (infinitely sharp at any zoom level)
 * - 100% native PDF text glyphs (sharp, selectable, copyable, searchable)
 * - Zero rasterization of the invoice layout or text
 * - Visually identical to the on-screen invoice preview (colors, layout, structure, fonts)
 * - Automatic multi-page handling with clean continuation headers and repeated table headers
 */

(function (window) {
  'use strict';

  // ─── Roboto Font (embedded Base64) for Indian Rupee ₹ Unicode support ─────
  // Roboto Regular & Bold — Google Fonts, OFL license.
  // Embedded so that U+20B9 (₹) renders as selectable/copyable text in jsPDF.
  /* eslint-disable */
  var _ROBOTO_REGULAR_B64 = '';
  var _ROBOTO_BOLD_B64 = '';
  /* eslint-enable */

  function _ensureRoboto(pdf) {
    if (!pdf || !pdf.getFontList) return;
    try {
      const fl = pdf.getFontList();
      if (fl && fl.Roboto) return;
      pdf.addFileToVFS('Roboto-Regular.ttf', _ROBOTO_REGULAR_B64);
      pdf.addFont('Roboto-Regular.ttf', 'Roboto', 'normal');
      pdf.addFileToVFS('Roboto-Bold.ttf', _ROBOTO_BOLD_B64);
      pdf.addFont('Roboto-Bold.ttf', 'Roboto', 'bold');
    } catch (_) {}
  }

  function drawPriceWithRupee(pdf, val, rightX, y, ptSize, color, isBold) {
    ptSize = ptSize || 8;
    color  = color  || [0, 0, 0];
    isBold = !!isBold;
    _ensureRoboto(pdf);

    if (val === null || val === undefined || val === '' || val === '—') {
      pdf.setFont('Roboto', isBold ? 'bold' : 'normal');
      pdf.setFontSize(ptSize);
      pdf.setTextColor.apply(pdf, color);
      pdf.text('—', rightX, y, { align: 'right' });
      return;
    }
    var num = typeof val === 'number' ? val : (parseFloat(String(val).replace(/[^0-9.-]+/g, '')) || 0);
    var numStr = num.toLocaleString('en-IN', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    });

    pdf.setFont('Roboto', isBold ? 'bold' : 'normal');
    pdf.setFontSize(ptSize);
    pdf.setTextColor.apply(pdf, color);
    // Single text() call — ₹ symbol + number together, right-aligned.
    // Because we use Roboto (a Unicode TTF), ₹ (U+20B9) renders correctly
    // and remains selectable / copyable in the PDF.
    pdf.text('₹' + numStr, rightX, y, { align: 'right' });
  }
  function formatMoney(val) {
    return (parseFloat(val) || 0).toLocaleString('en-IN', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    });
  }

  function sanitize(txt) {
    return String(txt || '');
  }

  function safeFormatDate(iso) {
    if (typeof formatDate === 'function') {
      return formatDate(iso);
    }
    if (!iso) return '';
    try {
      const d = new Date(iso);
      return isNaN(d.getTime()) ? iso : d.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });
    } catch {
      return iso;
    }
  }

  function getElementImageDataUrl(imgEl) {
    if (!imgEl) return null;
    if (imgEl.src && imgEl.src.startsWith('data:image/')) return imgEl.src;
    if (!imgEl.complete || imgEl.naturalWidth === 0) return null;
    try {
      const canvas = document.createElement('canvas');
      canvas.width = imgEl.naturalWidth;
      canvas.height = imgEl.naturalHeight;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(imgEl, 0, 0);
      return canvas.toDataURL('image/png');
    } catch (e) {
      return imgEl.src || null;
    }
  }

  function formatPackSize(str) {
    if (!str && str !== 0) return '—';
    return String(str).replace(/\b(ml|ltr|kg|gm)\b/gi, m => m.toUpperCase());
  }

  function formatTaxLabel(tt) {
    if (!tt || tt === 'NONE') return '';
    const m = String(tt).match(/^(I?GST)(\d+)$/i);
    if (m) return `${m[1].toUpperCase()} ${m[2]}%`;
    return String(tt);
  }

  function buildQrDataUrl(upi, companyName) {
    if (typeof window === 'undefined' || !window.QRCode) return null;
    try {
      const wrap = document.createElement('div');
      wrap.style.position = 'fixed';
      wrap.style.left = '-10000px';
      wrap.style.top = '0';
      wrap.style.width = '90px';
      wrap.style.height = '90px';
      wrap.style.visibility = 'hidden';
      document.body.appendChild(wrap);

      new window.QRCode(wrap, {
        text: `upi://pay?pa=${upi || '9427213943m@pnb'}&pn=${encodeURIComponent(companyName || 'Anjani Agri Care')}`,
        width: 90,
        height: 90,
        colorDark: '#000000',
        colorLight: '#ffffff',
        correctLevel: window.QRCode.CorrectLevel.M,
      });

      const qrCanvas = wrap.querySelector('canvas');
      if (qrCanvas) {
        const data = qrCanvas.toDataURL('image/png');
        wrap.remove();
        return data;
      }
      const qrImg = wrap.querySelector('img');
      if (qrImg?.src) {
        const data = qrImg.src;
        wrap.remove();
        return data;
      }
      wrap.remove();
    } catch (err) {
      console.warn('QR build error:', err);
    }
    return null;
  }

  function getQrDataUrl(upi, companyName) {
    const qrCanvas = document.querySelector('#qr-canvas canvas');
    if (qrCanvas) {
      try {
        return qrCanvas.toDataURL('image/png');
      } catch (e) {}
    }
    const qrImg = document.querySelector('#qr-canvas img');
    if (qrImg) {
      return getElementImageDataUrl(qrImg);
    }
    const upiVal = upi || document.getElementById('s-upi')?.value || '9427213943m@pnb';
    const cName = companyName || document.getElementById('s-company')?.value || 'Anjani Agri Care';
    return buildQrDataUrl(upiVal, cName);
  }

  const INDIAN_STATES = [
    'Andhra Pradesh', 'Arunachal Pradesh', 'Assam', 'Bihar', 'Chhattisgarh', 'Goa',
    'Gujarat', 'Haryana', 'Himachal Pradesh', 'Jharkhand', 'Karnataka', 'Kerala',
    'Madhya Pradesh', 'Maharashtra', 'Manipur', 'Meghalaya', 'Mizoram', 'Nagaland',
    'Odisha', 'Punjab', 'Rajasthan', 'Sikkim', 'Tamil Nadu', 'Telangana', 'Tripura',
    'Uttar Pradesh', 'Uttarakhand', 'West Bengal', 'Andaman and Nicobar Islands',
    'Chandigarh', 'Dadra and Nagar Haveli and Daman and Diu', 'Delhi',
    'Jammu and Kashmir', 'Ladakh', 'Lakshadweep', 'Puducherry'
  ];

  const GST_STATE_MAP = {
    '01': 'Jammu and Kashmir', '02': 'Himachal Pradesh', '03': 'Punjab', '04': 'Chandigarh',
    '05': 'Uttarakhand', '06': 'Haryana', '07': 'Delhi', '08': 'Rajasthan',
    '09': 'Uttar Pradesh', '10': 'Bihar', '11': 'Sikkim', '12': 'Arunachal Pradesh',
    '13': 'Nagaland', '14': 'Manipur', '15': 'Mizoram', '16': 'Tripura',
    '17': 'Meghalaya', '18': 'Assam', '19': 'West Bengal', '20': 'Jharkhand',
    '21': 'Odisha', '22': 'Chhattisgarh', '23': 'Madhya Pradesh', '24': 'Gujarat',
    '26': 'Dadra and Nagar Haveli and Daman and Diu', '27': 'Maharashtra', '29': 'Karnataka',
    '30': 'Goa', '31': 'Lakshadweep', '32': 'Kerala', '33': 'Tamil Nadu',
    '34': 'Puducherry', '35': 'Andaman and Nicobar Islands', '36': 'Telangana', '37': 'Andhra Pradesh',
    '38': 'Ladakh'
  };

  function resolveClientAddressAndState(clientOrAddr, fallbackCity, fallbackGstin, fallbackState, fallbackPin) {
    let rawAddr = '';
    let rawCity = '';
    let rawGst = '';
    let rawPin = '';
    let rawState = '';

    if (clientOrAddr && typeof clientOrAddr === 'object') {
      rawAddr = String(clientOrAddr.address || clientOrAddr.Address || clientOrAddr.cleanAddress || '').trim();
      rawCity = String(clientOrAddr.city || clientOrAddr.City || '').trim();
      rawGst = String(clientOrAddr.gst || clientOrAddr.gstin || clientOrAddr.GST || clientOrAddr.GSTIN || '').trim();
      rawPin = String(clientOrAddr.pincode || clientOrAddr.pin || clientOrAddr.Pin || clientOrAddr.Pincode || '').trim();
      rawState = String(clientOrAddr.state || clientOrAddr.State || '').trim();
    } else {
      rawAddr = String(clientOrAddr || '').trim();
      rawCity = String(fallbackCity || '').trim();
      rawGst = String(fallbackGstin || '').trim();
      rawState = String(fallbackState || '').trim();
      rawPin = String(fallbackPin || '').trim();
    }

    const isStateName = (str) => {
      if (!str) return null;
      const clean = str.trim().toLowerCase();
      for (let i = 0; i < INDIAN_STATES.length; i++) {
        if (INDIAN_STATES[i].toLowerCase() === clean) return INDIAN_STATES[i];
      }
      return null;
    };

    // 1. Detect GST state code if GST is available
    let gstState = '';
    const cleanGst = rawGst.toUpperCase().replace(/[^0-9A-Z]/g, '');
    if (cleanGst.length >= 2) {
      const code = cleanGst.slice(0, 2);
      if (GST_STATE_MAP[code]) {
        gstState = GST_STATE_MAP[code];
      }
    }

    const cityAsState = isStateName(rawCity);
    const addrAsState = isStateName(rawAddr);

    let finalState = isStateName(rawState) || (rawState ? rawState.trim() : '') || gstState;
    if (!finalState) {
      if (cityAsState) finalState = cityAsState;
      else if (addrAsState) finalState = addrAsState;
      else {
        const allText = rawAddr + ' ' + rawCity;
        for (let j = 0; j < INDIAN_STATES.length; j++) {
          const re = new RegExp('\\b' + INDIAN_STATES[j] + '\\b', 'i');
          if (re.test(allText)) {
            finalState = INDIAN_STATES[j];
            break;
          }
        }
      }
    }
    if (!finalState) finalState = '';

    // 2. Detect Pincode
    if (!rawPin) {
      const pm = (rawAddr + ' ' + rawCity).match(/\b\d{6}\b/);
      if (pm) rawPin = pm[0];
    }

    // 3. Build address parts
    let parts = [];
    if (rawAddr && !addrAsState) {
      parts.push(rawAddr);
    }
    if (rawCity && !cityAsState) {
      if (!rawAddr.toLowerCase().includes(rawCity.toLowerCase())) {
        parts.push(rawCity);
      }
    }

    if (parts.length === 0) {
      if (rawAddr && !addrAsState) parts.push(rawAddr);
      else if (rawCity && !cityAsState) parts.push(rawCity);
    }

    let combined = parts.join(', ');
    if (!combined && rawAddr && !addrAsState) combined = rawAddr;
    if (!combined && rawCity && !cityAsState) combined = rawCity;

    // Strip pincode
    if (rawPin) {
      combined = combined.replace(new RegExp('(?:-\\s*)?\\b' + rawPin + '\\b', 'gi'), '');
    }

    // Strip state name wherever it appears as a token
    if (finalState) {
      combined = combined
        .replace(new RegExp('(^|[,\\s]+)' + finalState + '(?=[,\\s]+|$)', 'gi'), '')
        .replace(new RegExp('\\b' + finalState + '\\b', 'gi'), '');
    }
    // Also strip any other Indian state name that might be present
    for (let k = 0; k < INDIAN_STATES.length; k++) {
      combined = combined
        .replace(new RegExp('(^|[,\\s]+)' + INDIAN_STATES[k] + '(?=[,\\s]+|$)', 'gi'), '')
        .replace(new RegExp('\\b' + INDIAN_STATES[k] + '\\b', 'gi'), '');
    }

    let cleanAddress = combined
      .replace(/^[,\s\-\/]+|[,\s\-\/]+$/g, '')
      .replace(/,\s*,+/g, ',')
      .replace(/\s+/g, ' ')
      .trim();

    return {
      cleanAddress: cleanAddress,
      state: finalState,
      pincode: rawPin
    };
  }

  function drawA4InvoicePdf(pdf, payload) {
    _ensureRoboto(pdf);
    const PW = 210, PH = 297;
    const margin = 13.5;
    const contentWidth = PW - margin * 2; // 183 mm
    const rightEdge = PW - margin; // 196.5 mm
    const isGst = payload.InvoiceType === 'GST' || (typeof document !== 'undefined' && document.body && document.body.classList.contains('gst-mode'));

    // Exact Brand & Preview Palette (Image 1 target design)
    const C_DARK_GREEN = [8, 40, 26];     // #08281A (Anjani Agri Care Primary Theme Green)
    const C_TEXT_MAIN  = [0, 0, 0];        // #000000 (Pure black headings/text as in Image 1)
    const C_TEXT_SLATE = [30, 41, 59];      // #1e293b
    const C_TEXT_MUTED = [100, 116, 139];   // #64748b (Slate 500)
    const C_BORDER     = [226, 232, 240];   // #e2e8f0 (Slate 200)
    const C_ROW_LINE   = [241, 245, 249];   // #f1f5f9 (Slate 100)
    const C_CARD_BG    = [248, 250, 252];   // #f8fafc (Slate 50)
    const C_ROW_ALT    = [249, 250, 251];   // #f9fafb (Gray 50)
    const C_DUE_RED    = [239, 68, 68];     // #ef4444 (Red 500)
    const C_TAX_BG     = [243, 247, 244];   // rgba(12, 57, 37, 0.05)
    const C_WHITE      = [255, 255, 255];

    const $ = id => document.getElementById(id);

    // Business details
    const companyName = payload.business?.company || $('s-company')?.value || $('p-company')?.textContent || 'Anjani Agri Care';
    const companyAddress = payload.business?.address || $('s-address')?.value || $('p-address')?.textContent || 'Sr. No. 67 and 68, Plot No. 33, Siddhi Vinayak Industrial Zone, At: Virva, Tal: Lodhika, Dist: Rajkot, Gujarat.';
    const companyPhone = payload.business?.phone || $('s-phone')?.value || ($('p-phone')?.textContent !== '-' ? $('p-phone')?.textContent : '') || '96646 75227';
    const companyEmail = payload.business?.email || $('s-email')?.value || $('p-email')?.textContent || 'anjaniagricare@gmail.com';
    const companyGstin = payload.business?.gstin || (isGst ? ($('s-gstin')?.value || $('p-gstin')?.textContent || '24AERFS1718Q1ZB') : '');
    const signatoryName = payload.business?.signatory || $('s-signatory')?.value || $('p-signatory')?.textContent || 'Tirth';

    // Invoice Meta
    const invNum = payload.InvoiceNumber || $('s-inv-num')?.value || $('p-inv-num')?.textContent || '001';
    const invDate = payload.Date || payload.date || payload.meta?.date || $('s-inv-date')?.value || $('p-inv-date')?.textContent || '';
    const dueDate = payload.DueDate || payload.dueDate || payload.meta?.dueDate || $('s-due-date')?.value || '';

    // Customer details
    const clientName = payload.customer?.name || payload.customer?.ClientName || $('s-client-name')?.value || $('p-client-name')?.textContent || 'Client Name';
    const clientAddress = payload.customer?.address || payload.customer?.Address || $('s-client-addr')?.value || '';
    const clientPhone = payload.customer?.contact || payload.customer?.phone || payload.customer?.Phone || payload.customer?.mobile || payload.customer?.Mobile || $('s-client-phone')?.value || '';
    const clientGstin = payload.customer?.gst || payload.customer?.gstin || payload.customer?.GST || payload.customer?.GSTIN || (isGst ? ($('s-client-gstin')?.value || '') : '');
    const clientState = payload.customer?.state || $('s-client-state')?.value || '';
    const clientPos = payload.customer?.placeOfSupply || $('s-place-supply')?.value || clientState || '';

    // Bank & Payment details
    const bankName = payload.bank?.name || $('s-bank-name')?.value || $('p-bank-name')?.textContent || '';
    const bankAcc = payload.bank?.account || $('s-bank-acc')?.value || $('p-bank-acc')?.textContent || '';
    const bankIfsc = payload.bank?.ifsc || $('s-bank-ifsc')?.value || $('p-bank-ifsc')?.textContent || '';
    const bankUpi = payload.bank?.upi || $('s-upi')?.value || ($('p-upi')?.textContent !== '-' && $('p-upi')?.textContent !== '—' ? $('p-upi')?.textContent : '') || '9427213943m@pnb';
    const showQr = $('qr-toggle')?.checked || payload.settings?.showQR;

    // Intro and Terms
    const introText = sanitize(payload.settings?.intro || $('s-intro')?.value || $('p-intro')?.textContent || '');
    const termsText = sanitize(payload.settings?.terms || $('s-terms')?.value || ($('p-terms')?.style.display !== 'none' ? $('p-terms')?.textContent : '') || '');

    // Rows and Totals
    const rawRows = (payload.rows && payload.rows.length) ? payload.rows : (window.rows || []);
    const dueAmount = parseFloat(payload.DueAmount || payload.customer?.dueAmount || $('s-client-due')?.value || 0) || 0;

    const taxType = typeof resolveTaxTypeFromInputs === 'function'
      ? resolveTaxTypeFromInputs()
      : (payload.taxType || payload.settings?.taxType || (payload.calculations && payload.calculations.taxType) || 'NONE');

    const subtotal = rawRows.reduce((s, r) => s + (parseFloat(r.taxableValue != null ? r.taxableValue : r.total) || 0), 0);

    const totals = typeof calculateInvoiceTotals === 'function'
      ? calculateInvoiceTotals(subtotal, taxType, dueAmount)
      : (payload.calculations ? { taxType: taxType, ...payload.calculations } : {
          subtotal: subtotal,
          grandTotal: subtotal + dueAmount,
          cgstAmount: 0,
          sgstAmount: 0,
          igstAmount: 0,
          totalTax: 0,
          cgstRate: 0,
          sgstRate: 0,
          igstRate: 0,
          taxType: taxType
        });

    let pageIndex = 1;
    let y = margin;

    // Continuation Page Top (No redundant header on 2nd+ page as requested)
    const drawContinuationHeader = () => {
      return margin;
    };

    // Table Header Bar (Image 1 dimensions and padding with rounded corners)
    const drawTableHeader = (curY) => {
      pdf.setFillColor(...C_DARK_GREEN);
      pdf.roundedRect(margin, curY, contentWidth, 8.5, 2.5, 2.5, 'F');

      pdf.setFont('helvetica', 'bold');
      pdf.setFontSize(8);
      pdf.setTextColor(...C_WHITE);

      const drawTotalColHeader = () => {
        _ensureRoboto(pdf);
        pdf.setFont('Roboto', 'bold');
        pdf.setFontSize(8);
        pdf.setTextColor(...C_WHITE);
        // ₹ (U+20B9) rendered via embedded Roboto TTF — selectable text
        pdf.text('TOTAL (₹)', rightEdge - 4, curY + 5.5, { align: 'right' });
      };

      // 7 Columns matching Image 1:
      // NO. (10), PRODUCTS (66), PACK SIZE (24), BOXES (16), QTY (UNITS) (22), RATE (₹) (20), TOTAL (₹) (24)
      pdf.setFont('helvetica', 'bold');
      pdf.setFontSize(8);
      pdf.setTextColor(...C_WHITE);

      pdf.text('NO.', margin + 5, curY + 5.5, { align: 'center' });
      pdf.text('PRODUCTS', margin + 12, curY + 5.5);
      pdf.text('PACK SIZE', margin + 88, curY + 5.5, { align: 'center' });
      pdf.text('BOXES', margin + 108, curY + 5.5, { align: 'center' });
      pdf.text('QTY (UNITS)', margin + 127, curY + 5.5, { align: 'center' });

      // RATE (₹) and TOTAL (₹)
      pdf.setFont('Roboto', 'bold');
      pdf.setFontSize(8);
      pdf.setTextColor(...C_WHITE);
      pdf.text('RATE (₹)', margin + 156, curY + 5.5, { align: 'right' });
      drawTotalColHeader();

      return curY + 8.5;
    };

    // ─── 1. FULL HEADER (Page 1 — Calibrated to Image 1) ──────────────────────
    const headerTop = margin;

    // 1A. Logo (Left)
    const logoEl = $('paper-logo') || $('navbar-logo') || (typeof document !== 'undefined' ? (document.querySelector('#view-invoice-paper img') || document.querySelector('#dispatch-slip-paper img') || document.querySelector('img[alt*="Afield"]') || document.querySelector('img[alt*="Logo"]')) : null);
    if (logoEl && logoEl.complete && logoEl.naturalWidth > 0 && logoEl.style.display !== 'none') {
      try {
        const logoData = getElementImageDataUrl(logoEl);
        if (logoData) {
          const maxLogoW = 32, maxLogoH = 26;
          const aspect = (logoEl.naturalWidth || 1) / (logoEl.naturalHeight || 1);
          let logoW = maxLogoW;
          let logoH = logoW / aspect;
          if (logoH > maxLogoH) {
            logoH = maxLogoH;
            logoW = logoH * aspect;
          }
          pdf.addImage(logoData, 'JPEG', margin + 2, headerTop + 3.5, logoW, logoH);
        }
      } catch (err) {
        console.warn('Could not draw logo in PDF:', err);
      }
    }

    // 1B. Company Info (Center — Image 1 proportions)
    const centerX = 105;
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(16.5);
    pdf.setTextColor(...C_DARK_GREEN);
    pdf.text(companyName, centerX, headerTop + 7.5, { align: 'center' });

    // Helper to format company address ensuring "At:" stays at the end of line 1
    const getCompanyAddressLines = (addr, maxW) => {
      if (!addr) return [];
      if (addr.includes('At:')) {
        const parts = addr.split('At:');
        let p1 = parts[0].trim();
        if (!p1.endsWith(',')) p1 += ',';
        p1 += ' At:';
        let p2 = parts.slice(1).join('At:').trim();
        return [p1, p2];
      }
      return pdf.splitTextToSize(addr, maxW);
    };

    pdf.setFont('helvetica', 'normal');
    pdf.setFontSize(8.25);
    pdf.setTextColor(...C_TEXT_MAIN);

    const addrLines = getCompanyAddressLines(companyAddress, 88);
    let curCenterY = headerTop + 12.0;
    addrLines.forEach(line => {
      pdf.text(line, centerX, curCenterY, { align: 'center' });
      curCenterY += 3.8;
    });

    const contactStr = [companyPhone, companyEmail].filter(Boolean).join(' | ');
    if (contactStr) {
      pdf.text(contactStr, centerX, curCenterY, { align: 'center' });
      curCenterY += 3.8;
    }
    if (companyGstin) {
      pdf.text(`GSTIN: ${companyGstin}`, centerX, curCenterY, { align: 'center' });
      curCenterY += 3.8;
    }

    // 1C. Right Side Meta / Badge (Calibrated to Image 1)
    const drawMetaRow = (label, val, rowY) => {
      pdf.setFont('helvetica', 'normal');
      pdf.setFontSize(8.5);
      const lw = pdf.getTextWidth(label + ' ');
      pdf.setFont('helvetica', 'bold');
      const vw = pdf.getTextWidth(val);
      const startX = rightEdge - (lw + vw);

      pdf.setFont('helvetica', 'normal');
      pdf.setTextColor(...C_TEXT_MAIN);
      pdf.text(label + ' ', startX, rowY);

      pdf.setFont('helvetica', 'bold');
      pdf.text(val, startX + lw, rowY);
    };

    if (!isGst) {
      const badgeW = 36, badgeH = 8.5;
      const badgeX = rightEdge - badgeW;
      pdf.setFillColor(...C_DARK_GREEN);
      pdf.roundedRect(badgeX, headerTop + 4, badgeW, badgeH, 2.5, 2.5, 'F');

      pdf.setFont('helvetica', 'bold');
      pdf.setFontSize(9.5);
      pdf.setTextColor(...C_WHITE);
      pdf.text('INVOICE', badgeX + (badgeW / 2), headerTop + 9.5, { align: 'center' });

      let metaY = headerTop + 18.5;
      drawMetaRow('Invoice No:', invNum, metaY);

      metaY += 5.2;
      drawMetaRow('Date:', safeFormatDate(invDate), metaY);

      if (dueDate) {
        metaY += 5.2;
        drawMetaRow('Due:', safeFormatDate(dueDate), metaY);
      }
    } else {
      let metaY = headerTop + 8.5;
      drawMetaRow('Invoice No:', invNum, metaY);

      metaY += 5.2;
      drawMetaRow('Date:', safeFormatDate(invDate || new Date().toISOString().split('T')[0]), metaY);

      if (dueDate) {
        metaY += 5.2;
        drawMetaRow('Due:', safeFormatDate(dueDate), metaY);
      }

      const dispNo = payload.meta?.dispatchNo || payload.dispatchNo || (typeof window !== 'undefined' ? window.currentDispatchNo : '');
      if (dispNo) {
        metaY += 5.2;
        drawMetaRow('Dispatch:', dispNo, metaY);
      }
      const vehNo = payload.meta?.vehicleNo || payload.vehicleNo || (typeof window !== 'undefined' ? window.currentVehicleNo : '');
      if (vehNo) {
        metaY += 5.2;
        drawMetaRow('Vehicle:', vehNo, metaY);
      }
    }

    let headerBottom = Math.max(curCenterY + 2.5, headerTop + 35.5);

    // 1D. GST Document Strip (Debit Memo | Tax Invoice | Original)
    if (isGst) {
      headerBottom += 2.5;
      pdf.setFont('helvetica', 'bold');
      pdf.setFontSize(8.5);
      pdf.setTextColor(...C_TEXT_MAIN);
      pdf.text('Debit Memo', margin, headerBottom);
      pdf.setFontSize(9.5);
      pdf.text('Tax Invoice', centerX, headerBottom, { align: 'center' });
      pdf.setFontSize(8.5);
      pdf.text('Original', rightEdge, headerBottom, { align: 'right' });
      headerBottom += 4.5;
    }

    // 1E. Solid Green Header Divider Line (0.8 mm width = 3px)
    pdf.setDrawColor(...C_DARK_GREEN);
    pdf.setLineWidth(0.8);
    pdf.line(margin, headerBottom, rightEdge, headerBottom);

    y = headerBottom + 7;

    // ─── 2. BILL FROM / BILL TO CARD (Calibrated to Image 3) ─────────────────
    const colW = (contentWidth - 14) / 2; // ~84 mm
    const leftColX = margin + 5;
    const rightColX = margin + colW + 9;

    const formatPhoneDisplay = (p) => {
      if (!p) return '';
      const digits = String(p).replace(/\D/g, '');
      if (digits.length === 10) return `${digits.slice(0, 5)} ${digits.slice(5)}`;
      if (digits.length === 12 && digits.startsWith('91')) return `+91 ${digits.slice(2, 7)} ${digits.slice(7)}`;
      return String(p).trim();
    };

    // Company details
    const compName = companyName || 'Anjani Agri Care';
    const compState = (document.getElementById('s-company-state')?.value || 'Gujarat').trim();
    const compPin = (document.getElementById('s-company-pincode')?.value || '360024').trim();
    const compPhone = formatPhoneDisplay(companyPhone || '96646 75227');
    const compGstin = (companyGstin || '24AERFS1718Q1ZB').trim();

    // Clean company address
    let cleanCompAddr = (companyAddress || 'Sr. No. 67 and 68, Plot No. 33, Siddhi Vinayak Industrial Zone, At: Virva, Tal: Lodhika, Dist: Rajkot, Gujarat.')
      .replace(/,?\s*(?:Gujarat)?\s*(?:-\s*)?360024\s*$/i, '')
      .replace(/,?\s*Gujarat\s*$/i, '')
      .replace(/\bAnd\b/g, 'and')
      .trim();
    const bFromLines = pdf.splitTextToSize(cleanCompAddr, colW - 6);

    // Client details
    const cName = sanitize(clientName || 'Client Name').replace(/\(([a-z])/g, (m, l) => '(' + l.toUpperCase());
    const cPhone = formatPhoneDisplay(clientPhone);
    const cGstin = (clientGstin || '').trim();

    const resolvedClient = resolveClientAddressAndState({
      address: clientAddress,
      city: payload.customer?.city || payload.customer?.City || '',
      state: (document.getElementById('s-client-state')?.value || clientState || payload.customer?.state || ''),
      pincode: (document.getElementById('s-client-pincode')?.value || payload.customer?.pincode || payload.customer?.pin || ''),
      gstin: cGstin
    });

    const cState = resolvedClient.state;
    const cPin = resolvedClient.pincode;
    const cleanClientAddr = resolvedClient.cleanAddress;
    const bToLines = cleanClientAddr ? pdf.splitTextToSize(cleanClientAddr, colW - 6) : [];

    const maxAddrLines = Math.max(bFromLines.length, bToLines.length, 1);
    const cardH = 20 + (maxAddrLines * 3.6) + 8.5;

    // Background card with rounded corners
    pdf.setFillColor(...C_CARD_BG);
    pdf.setDrawColor(...C_BORDER);
    pdf.setLineWidth(0.3);
    pdf.roundedRect(margin, y, contentWidth, cardH, 2.8, 2.8, 'FD');

    // Headers
    let textY = y + 5.5;
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(7.5);
    pdf.setTextColor(...C_DARK_GREEN);
    pdf.text('BILL FROM', leftColX, textY);
    pdf.text('BILL TO', rightColX, textY);

    // Names
    textY += 4.5;
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(9.5);
    pdf.setTextColor(...C_TEXT_MAIN);
    pdf.text(compName, leftColX, textY);
    pdf.text(cName, rightColX, textY);

    // Addresses
    textY += 3.8;
    pdf.setFont('helvetica', 'normal');
    pdf.setFontSize(7.8);
    pdf.setTextColor(30, 41, 59);

    let fY = textY;
    bFromLines.forEach(l => {
      pdf.text(l, leftColX, fY);
      fY += 3.5;
    });

    let tY = textY;
    bToLines.forEach(l => {
      pdf.text(l, rightColX, tY);
      tY += 3.5;
    });

    const kvStartY = textY + (maxAddrLines * 3.5) + 0.8;
    const subColOffset = 38; // Spacing between State and Pincode / Phone and GSTIN

    // Key-Values Row 1: State & Pincode
    let curKvY = kvStartY;
    pdf.setFontSize(7.5);

    // Left side (Bill From): State and Pincode
    pdf.setFont('helvetica', 'normal');
    pdf.setTextColor(71, 85, 105);
    pdf.text('State: ', leftColX, curKvY);
    pdf.setFont('helvetica', 'bold');
    pdf.setTextColor(15, 23, 42);
    pdf.text(compState, leftColX + pdf.getTextWidth('State: '), curKvY);

    if (compPin) {
      pdf.setFont('helvetica', 'normal');
      pdf.setTextColor(71, 85, 105);
      pdf.text('Pincode: ', leftColX + subColOffset, curKvY);
      pdf.setFont('helvetica', 'bold');
      pdf.setTextColor(15, 23, 42);
      pdf.text(compPin, leftColX + subColOffset + pdf.getTextWidth('Pincode: '), curKvY);
    }

    // Right side (Bill To): Fluid State and Pincode
    if (cState && cPin) {
      pdf.setFont('helvetica', 'normal');
      pdf.setTextColor(71, 85, 105);
      pdf.text('State: ', rightColX, curKvY);
      pdf.setFont('helvetica', 'bold');
      pdf.setTextColor(15, 23, 42);
      pdf.text(cState, rightColX + pdf.getTextWidth('State: '), curKvY);

      pdf.setFont('helvetica', 'normal');
      pdf.setTextColor(71, 85, 105);
      pdf.text('Pincode: ', rightColX + subColOffset, curKvY);
      pdf.setFont('helvetica', 'bold');
      pdf.setTextColor(15, 23, 42);
      pdf.text(cPin, rightColX + subColOffset + pdf.getTextWidth('Pincode: '), curKvY);
    } else if (cState) {
      pdf.setFont('helvetica', 'normal');
      pdf.setTextColor(71, 85, 105);
      pdf.text('State: ', rightColX, curKvY);
      pdf.setFont('helvetica', 'bold');
      pdf.setTextColor(15, 23, 42);
      pdf.text(cState, rightColX + pdf.getTextWidth('State: '), curKvY);
    } else if (cPin) {
      // Reposition Pincode to column start when State is missing
      pdf.setFont('helvetica', 'normal');
      pdf.setTextColor(71, 85, 105);
      pdf.text('Pincode: ', rightColX, curKvY);
      pdf.setFont('helvetica', 'bold');
      pdf.setTextColor(15, 23, 42);
      pdf.text(cPin, rightColX + pdf.getTextWidth('Pincode: '), curKvY);
    }

    // Key-Values Row 2: Phone & GSTIN
    curKvY += 3.8;

    // Left side (Bill From): Phone and GSTIN
    if (compPhone) {
      pdf.setFont('helvetica', 'normal');
      pdf.setTextColor(71, 85, 105);
      pdf.text('Phone: ', leftColX, curKvY);
      pdf.setFont('helvetica', 'bold');
      pdf.setTextColor(15, 23, 42);
      pdf.text(compPhone, leftColX + pdf.getTextWidth('Phone: '), curKvY);
    }
    if (compGstin) {
      pdf.setFont('helvetica', 'normal');
      pdf.setTextColor(71, 85, 105);
      pdf.text('GSTIN: ', leftColX + subColOffset, curKvY);
      pdf.setFont('helvetica', 'bold');
      pdf.setTextColor(15, 23, 42);
      pdf.text(compGstin, leftColX + subColOffset + pdf.getTextWidth('GSTIN: '), curKvY);
    }

    // Right side (Bill To): Fluid Phone and GSTIN
    if (cPhone && cGstin) {
      pdf.setFont('helvetica', 'normal');
      pdf.setTextColor(71, 85, 105);
      pdf.text('Phone: ', rightColX, curKvY);
      pdf.setFont('helvetica', 'bold');
      pdf.setTextColor(15, 23, 42);
      pdf.text(cPhone, rightColX + pdf.getTextWidth('Phone: '), curKvY);

      pdf.setFont('helvetica', 'normal');
      pdf.setTextColor(71, 85, 105);
      pdf.text('GSTIN: ', rightColX + subColOffset, curKvY);
      pdf.setFont('helvetica', 'bold');
      pdf.setTextColor(15, 23, 42);
      pdf.text(cGstin, rightColX + subColOffset + pdf.getTextWidth('GSTIN: '), curKvY);
    } else if (cPhone) {
      pdf.setFont('helvetica', 'normal');
      pdf.setTextColor(71, 85, 105);
      pdf.text('Phone: ', rightColX, curKvY);
      pdf.setFont('helvetica', 'bold');
      pdf.setTextColor(15, 23, 42);
      pdf.text(cPhone, rightColX + pdf.getTextWidth('Phone: '), curKvY);
    } else if (cGstin) {
      // Reposition GSTIN to column start when Phone is missing
      pdf.setFont('helvetica', 'normal');
      pdf.setTextColor(71, 85, 105);
      pdf.text('GSTIN: ', rightColX, curKvY);
      pdf.setFont('helvetica', 'bold');
      pdf.setTextColor(15, 23, 42);
      pdf.text(cGstin, rightColX + pdf.getTextWidth('GSTIN: '), curKvY);
    }

    y += cardH + 7;

    // ─── 3. INTRO TEXT (Calibrated to Image 1) ────────────────────────────────
    if (introText.trim()) {
      pdf.setFont('helvetica', 'normal');
      pdf.setFontSize(8.5);
      pdf.setTextColor(...C_TEXT_MAIN);
      const introLines = introText.trim().split('\n');
      introLines.forEach(l => {
        const wrapped = pdf.splitTextToSize(l, contentWidth);
        wrapped.forEach(wl => {
          pdf.text(wl, margin, y);
          y += 4.0;
        });
      });
      y += 3.5;
    }

    // ─── 4. ITEMS TABLE ────────────────────────────────────────────────────────
    y = drawTableHeader(y);

    rawRows.forEach((row, i) => {
      const brandName = sanitize(row.brand || '');
      const productName = sanitize(row.name || '');
      const productDesc = sanitize(row.desc || '');
      const packaging = sanitize(row.packaging || '');
      const boxes = parseFloat(row.boxes) || 0;
      const loose = parseFloat(row.loose) || 0;
      const unitsPerBox = parseInt(row.unitsPerBox, 10) || 0;
      const totalUnits = parseFloat(row.totalUnits != null ? row.totalUnits : row.qty) || 0;
      const totalVolume = parseFloat(row.totalVolume) || 0;
      const volumeUnit = sanitize(row.volumeUnit || 'L');
      const qtyUnit = sanitize(row.qtyUnit || 'Bottles');
      const priceBasis = row.priceBasis || 'per_unit';
      const discountPct = parseFloat(row.discountPct) || 0;
      const priceVal = parseFloat(row.price) || 0;

      // Packaging breakdown line
      let packLine = '';
      if (boxes > 0 || loose > 0) {
        const bStr = boxes > 0 ? `${boxes} Box${boxes === 1 ? '' : 'es'}` : '';
        const lStr = loose > 0 ? `${loose} Loose` : '';
        const combo = [bStr, lStr].filter(Boolean).join(' + ');
        const volStr = totalVolume > 0 ? ` (${totalVolume} ${volumeUnit})` : '';
        packLine = `${packaging ? packaging + ' | ' : ''}${combo}${volStr}`;
      } else if (packaging) {
        const volStr = totalVolume > 0 ? ` (${totalVolume} ${volumeUnit})` : '';
        packLine = `${packaging}${volStr}`;
      }

      // Quantity display
      const qtyStr = totalUnits > 0 ? String(totalUnits) : String(row.qty || '—');

      // Price / Rate label
      const priceSuffix = priceBasis === 'per_box' ? '/bx' : '';

      // Taxable and total calculations
      let taxableVal = parseFloat(row.taxableValue) || 0;
      if (!taxableVal) {
        const billedQty = priceBasis === 'per_box' ? (boxes + (unitsPerBox > 0 ? loose / unitsPerBox : 0)) : totalUnits;
        const raw = billedQty * priceVal;
        taxableVal = Math.round((raw - (raw * (discountPct / 100))) * 100) / 100;
      }

      // Column 7 TOTAL (₹) is line item total (taxable amount before GST in GST mode)
      let totalVal = taxableVal > 0 ? taxableVal : (parseFloat(row.total) || 0);

      pdf.setFont('helvetica', 'normal');
      pdf.setFontSize(8);

      let nameLines = [], descLines = [];
      nameLines = pdf.splitTextToSize(productName, 72);
      if (productDesc && productDesc !== packaging && productDesc !== productName) {
        pdf.setFontSize(7);
        descLines = pdf.splitTextToSize(productDesc, 72);
      }

      const textLinesCount = nameLines.length + (descLines.length ? 1 : 0);
      const rowH = Math.max(9.5, textLinesCount * 3.8 + 3.2);

      // Multi-page check
      if (y + rowH > PH - margin - 22) {
        pdf.addPage();
        pageIndex++;
        y = drawContinuationHeader();
        y = drawTableHeader(y);
      }

      // Alternating Row Background
      if (i % 2 === 1) {
        pdf.setFillColor(...C_ROW_ALT);
        pdf.rect(margin, y, contentWidth, rowH, 'F');
      } else {
        pdf.setFillColor(...C_WHITE);
        pdf.rect(margin, y, contentWidth, rowH, 'F');
      }

      // Row Divider Line
      pdf.setDrawColor(...C_ROW_LINE);
      pdf.setLineWidth(0.25);
      pdf.line(margin, y + rowH, rightEdge, y + rowH);

      // Draw Row Cells
      const cellY = y + 5.5;
      pdf.setFont('helvetica', 'normal');
      pdf.setFontSize(8);
      pdf.setTextColor(...C_TEXT_MAIN);

      // Col 1: NO.
      pdf.text(String(i + 1), margin + 5, cellY, { align: 'center' });

      // Col 2: PRODUCTS
      pdf.setFont('helvetica', 'bold');
      let nY = cellY;
      nameLines.forEach(nl => {
        pdf.text(nl, margin + 12, nY);
        nY += 3.8;
      });
      if (descLines.length) {
        pdf.setFont('helvetica', 'normal');
        pdf.setFontSize(7);
        pdf.setTextColor(...C_TEXT_MUTED);
        descLines.forEach(dl => {
          pdf.text(dl, margin + 12, nY);
          nY += 3.3;
        });
        pdf.setTextColor(...C_TEXT_MAIN);
        pdf.setFontSize(8);
      }

      // Col 3: PACK SIZE
      pdf.setFont('helvetica', 'normal');
      const packStr = formatPackSize(row.packaging || packaging || '—');
      pdf.text(packStr, margin + 88, cellY, { align: 'center' });

      // Col 4: BOXES
      const boxesCount = String(row.boxes > 0 ? row.boxes : (boxes > 0 ? boxes : 0));
      pdf.text(boxesCount, margin + 108, cellY, { align: 'center' });

      // Col 5: QTY (UNITS)
      pdf.setFont('helvetica', 'bold');
      pdf.setTextColor(...C_DARK_GREEN);
      const unitsCount = String(totalUnits > 0 ? totalUnits : (row.qty || 0));
      pdf.text(unitsCount, margin + 127, cellY, { align: 'center' });
      pdf.setTextColor(...C_TEXT_MAIN);
      pdf.setFont('helvetica', 'normal');

      // Col 6: RATE (₹)
      drawPriceWithRupee(pdf, priceVal, margin + 156, cellY, 8, C_TEXT_MAIN, false);
      if (priceSuffix || discountPct > 0) {
        pdf.setFontSize(6.5);
        pdf.setTextColor(...C_TEXT_MUTED);
        const subNote = [priceSuffix ? priceSuffix : '', discountPct > 0 ? `-${discountPct}%` : ''].filter(Boolean).join(' ');
        pdf.text(subNote, margin + 156, cellY + 3.2, { align: 'right' });
        pdf.setTextColor(...C_TEXT_MAIN);
        pdf.setFontSize(8);
      }

      // Col 7: TOTAL (₹)
      drawPriceWithRupee(pdf, totalVal, rightEdge - 4, cellY, 8, C_TEXT_MAIN, true);

      y += rowH;
    });

    y += 6;

    // ─── 5. TOTALS BOX (Calibrated to Image 1) ─────────────────────────────────
    const totalsBoxW = 74;
    const totalsX = rightEdge - totalsBoxW;

    const taxRowsList = [];
    if (isGst && totals.taxType !== 'NONE') {
      if (totals.cgstAmount > 0) taxRowsList.push({ label: `CGST (${totals.cgstRate}%)`, val: totals.cgstAmount });
      if (totals.sgstAmount > 0) taxRowsList.push({ label: `SGST (${totals.sgstRate}%)`, val: totals.sgstAmount });
      if (totals.igstAmount > 0) taxRowsList.push({ label: `IGST (${totals.igstRate}%)`, val: totals.igstAmount });
      if (totals.totalTax > 0) taxRowsList.push({ label: 'Total GST', val: totals.totalTax, bold: true });
    }

    const hasDue = dueAmount > 0;
    const rowCount = 1 + (isGst && totals.taxType !== 'NONE' ? 1 + taxRowsList.length : 0) + (hasDue ? 1 : 0);
    const totalBoxH = rowCount * 7.5 + 9.5;

    // Check if Totals fits
    if (y + totalBoxH + 45 > PH - margin) {
      pdf.addPage();
      pageIndex++;
      y = drawContinuationHeader();
    }

    // Draw Box Outline with rounded corners
    pdf.setDrawColor(...C_BORDER);
    pdf.setLineWidth(0.3);
    pdf.setFillColor(...C_WHITE);
    pdf.roundedRect(totalsX, y, totalsBoxW, totalBoxH, 2.8, 2.8, 'FD');

    let curTotalsY = y;

    // Row 1: Subtotal
    pdf.setFont('helvetica', 'normal');
    pdf.setFontSize(8.5);
    pdf.setTextColor(...C_TEXT_MAIN);
    pdf.text('Subtotal', totalsX + 4.5, curTotalsY + 5.2);
    drawPriceWithRupee(pdf, totals.subtotal, rightEdge - 4.5, curTotalsY + 5.2, 8.5, C_TEXT_MAIN, true);

    curTotalsY += 7.5;
    pdf.setDrawColor(...C_ROW_LINE);
    pdf.setLineWidth(0.2);
    pdf.line(totalsX, curTotalsY, rightEdge, curTotalsY);

    // If GST, Tax Type Banner + Details
    if (isGst && totals.taxType !== 'NONE') {
      pdf.setFillColor(...C_TAX_BG);
      pdf.rect(totalsX, curTotalsY, totalsBoxW, 7.5, 'F');
      pdf.setFont('helvetica', 'bold');
      pdf.setFontSize(8);
      pdf.setTextColor(...C_DARK_GREEN);
      const taxLabel = formatTaxLabel(totals.taxType || taxType || 'GST12');
      pdf.text(String(taxLabel || 'GST 12%'), totalsX + 4.5, curTotalsY + 5.0);

      curTotalsY += 7.5;
      pdf.line(totalsX, curTotalsY, rightEdge, curTotalsY);

      taxRowsList.forEach(tr => {
        pdf.setFont('helvetica', tr.bold ? 'bold' : 'normal');
        pdf.setFontSize(8);
        pdf.setTextColor(...C_TEXT_MAIN);
        pdf.text(tr.label, totalsX + 6.5, curTotalsY + 5.0);
        drawPriceWithRupee(pdf, tr.val, rightEdge - 4.5, curTotalsY + 5.0, 8, C_TEXT_MAIN, true);

        curTotalsY += 7.5;
        pdf.line(totalsX, curTotalsY, rightEdge, curTotalsY);
      });
    }

    // Previous Due Row
    if (hasDue) {
      pdf.setFont('helvetica', 'bold');
      pdf.setFontSize(8.5);
      pdf.setTextColor(...C_DUE_RED);
      pdf.text('Previous Due', totalsX + 4.5, curTotalsY + 5.2);
      drawPriceWithRupee(pdf, dueAmount, rightEdge - 4.5, curTotalsY + 5.2, 8.5, C_DUE_RED, true);

      curTotalsY += 7.5;
      pdf.setDrawColor(...C_ROW_LINE);
      pdf.line(totalsX, curTotalsY, rightEdge, curTotalsY);
    }

    // Grand Total Bar (Clipped to outer card rounded corners so bottom corners are rounded)
    pdf.saveGraphicsState();
    pdf.roundedRect(totalsX, y, totalsBoxW, totalBoxH, 2.8, 2.8, null);
    pdf.clip();
    pdf.discardPath();

    pdf.setFillColor(...C_DARK_GREEN);
    pdf.rect(totalsX, curTotalsY, totalsBoxW, 9.5, 'F');
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(9.5);
    pdf.setTextColor(...C_WHITE);
    pdf.text('GRAND TOTAL', totalsX + 4.5, curTotalsY + 6.2);
    drawPriceWithRupee(pdf, totals.grandTotal, rightEdge - 4.5, curTotalsY + 6.2, 9.5, C_WHITE, true);

    pdf.restoreGraphicsState();

    // Re-stroke outer box border cleanly
    pdf.setDrawColor(...C_BORDER);
    pdf.setLineWidth(0.3);
    pdf.roundedRect(totalsX, y, totalsBoxW, totalBoxH, 2.8, 2.8, 'D');

    y = curTotalsY + 14;

    // ─── 6. TERMS & CONDITIONS (Calibrated to Image 1) ─────────────────────────
    if (termsText.trim()) {
      pdf.setFont('helvetica', 'bold');
      pdf.setFontSize(9);
      pdf.setTextColor(...C_DARK_GREEN);
      pdf.text('Terms & Conditions', margin, y);

      pdf.setFont('helvetica', 'normal');
      pdf.setFontSize(7.5);
      pdf.setTextColor(...C_TEXT_SLATE);
      const termLines = termsText.trim().split('\n');
      let tY = y + 4.5;
      termLines.forEach(tl => {
        const wrapped = pdf.splitTextToSize(tl, contentWidth);
        wrapped.forEach(wl => {
          pdf.text(wl, margin, tY);
          tY += 3.8;
        });
      });
      y = tY + 5;
    }

    // ─── 7. FOOTER SECTION ───────────────────────────────────────────────────
    const footerH = 34;
    if (y + footerH > PH - margin) {
      pdf.addPage();
      pageIndex++;
      drawContinuationHeader();
      y = PH - margin - footerH;
    } else {
      y = Math.max(y + 6, PH - margin - footerH);
    }

    const footerY = y;

    // Divider Line
    pdf.setDrawColor(...C_BORDER);
    pdf.setLineWidth(0.3);
    pdf.line(margin, footerY, rightEdge, footerY);

    // 7A. Left: Payment Details (Headings always drawn as requested; values empty/dashed if not provided)
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(8.5);
    pdf.setTextColor(...C_DARK_GREEN);
    pdf.text('Payment Details', margin, footerY + 5.5);

    const bankLines = [
      { label: 'Bank: ', val: bankName || '—' },
      { label: 'A/C No.: ', val: bankAcc || '—' },
      { label: 'IFSC: ', val: bankIfsc || '—' },
      { label: 'UPI: ', val: bankUpi || '—' }
    ];

    let bLineY = footerY + 10.0;
    bankLines.forEach(bl => {
      pdf.setFont('helvetica', 'bold');
      pdf.setFontSize(7.5);
      pdf.setTextColor(...C_TEXT_MAIN);
      pdf.text(bl.label, margin, bLineY);

      const lblW = pdf.getTextWidth(bl.label);
      pdf.setFont('helvetica', 'normal');
      pdf.text(bl.val, margin + lblW + 1, bLineY);
      bLineY += 4.0;
    });

    // 7B. Center: QR Code (if enabled)
    if (showQr && bankUpi && bankUpi.trim()) {
      const qrDataUrl = getQrDataUrl(bankUpi, companyName) || buildQrDataUrl(bankUpi, companyName);
      if (qrDataUrl) {
        try {
          pdf.addImage(qrDataUrl, 'PNG', 94, footerY + 3.5, 20, 20);
          pdf.setFont('helvetica', 'bold');
          pdf.setFontSize(7);
          pdf.setTextColor(...C_TEXT_MUTED);
          pdf.text('Scan to Pay', 104, footerY + 26.5, { align: 'center' });
        } catch (err) {
          console.warn('QR image draw skipped:', err);
        }
      }
    }

    // 7C. Right: Authorized Signature
    const sigCenterX = 174.5;
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(8.5);
    pdf.setTextColor(...C_TEXT_MAIN);
    pdf.text('Authorized Signature', sigCenterX, footerY + 5.5, { align: 'center' });

    // Draw "Tirth" as signature text
    pdf.setFont('helvetica', 'bolditalic');
    pdf.setFontSize(13);
    pdf.setTextColor(...C_DARK_GREEN);
    pdf.text('Tirth', sigCenterX, footerY + 13.5, { align: 'center' });

    // Signature dividing line
    pdf.setDrawColor(...C_BORDER);
    pdf.setLineWidth(0.3);
    pdf.line(sigCenterX - 18, footerY + 16.5, sigCenterX + 18, footerY + 16.5);

    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(8);
    pdf.setTextColor(...C_TEXT_MAIN);
    pdf.text(signatoryName || 'Authorized Signatory', sigCenterX, footerY + 21.5, { align: 'center' });
  }

  async function generateAndDownloadInvoicePDF() {
    const $ = id => document.getElementById(id);
    const rowsList = window.rows || [];

    // Validation: At least one row required with quantity and price
    if (!rowsList.length || !rowsList[0]) {
      if (typeof toast === 'function') toast('At least one item is required', 'error');
      return;
    }
    const firstItem = rowsList[0];
    if (!firstItem.qty || parseFloat(firstItem.qty) <= 0) {
      if (typeof toast === 'function') toast('First item: Quantity is required', 'error');
      return;
    }
    if (!firstItem.price || parseFloat(firstItem.price) <= 0) {
      if (typeof toast === 'function') toast('First item: Unit Price is required', 'error');
      return;
    }

    const btn = $('pdf-btn');
    const mobBtn = $('mob-pdf-btn');
    if (btn) {
      btn.innerHTML = '<span class="material-symbols-outlined" style="animation:spin 1s linear infinite">autorenew</span> Generating…';
      btn.disabled = true;
    }
    if (mobBtn) mobBtn.disabled = true;

    try {
      let saveResult;
      if (typeof saveToCloud === 'function') {
        try {
          saveResult = await saveToCloud(true);
        } catch (e) {
          console.warn('Auto-save before PDF failed:', e);
        }
      }

      const payload = saveResult?.payload || (typeof extractInvoiceJSON === 'function' ? extractInvoiceJSON(window.currentInvoiceId) : {});
      const invNum = payload.InvoiceNumber || $('s-inv-num')?.value || $('p-inv-num')?.textContent || '001';

      if (!window.jspdf || !window.jspdf.jsPDF) {
        throw new Error('jsPDF library not loaded');
      }

      const { jsPDF } = window.jspdf;
      const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });

      drawA4InvoicePdf(pdf, payload);

      const isDispatch = !!(payload.dispatchNo || (typeof window !== 'undefined' && window.currentDispatchNo) || (payload.type === 'dispatch') || String(invNum || '').startsWith('INV-'));
      const filename = getStandardInvoicePdfFilename(invNum, isDispatch);

      const saveBlobFn = (typeof window !== 'undefined' && window.savePdfBlob) ? window.savePdfBlob : (typeof savePdfBlob === 'function' ? savePdfBlob : null);
      if (saveBlobFn) {
        saveBlobFn(pdf, filename);
      } else {
        if (typeof window !== 'undefined') {
          window._lastDownloadedInvoicePdf = filename;
          if (typeof window._onPdfSaved === 'function') {
            try { window._onPdfSaved(filename); } catch (_) {}
          }
        }
        pdf.save(filename);
      }

      // Always guarantee saving to history cache upon downloading PDF
      try {
        const uniqueId = window.currentInvoiceId || payload.meta?.uniqueId || (saveResult && saveResult.uniqueId) || ('INV-' + Date.now().toString(36).toUpperCase());
        window.currentInvoiceId = uniqueId;
        payload.meta = payload.meta || {};
        payload.meta.uniqueId = uniqueId;
        payload.meta.invoiceNumber = invNum;
        payload.InvoiceNumber = invNum;

        if (typeof safeStorage !== 'undefined') {
          safeStorage.setItem('inv_doc_' + uniqueId, JSON.stringify(payload));
          let history = [];
          try {
            history = JSON.parse(safeStorage.getItem('invoice_history_cache') || '[]');
          } catch (_) { history = []; }

          const summary = {
            uniqueId: uniqueId,
            invoiceNumber: invNum,
            date: payload.meta?.date || payload.Date || new Date().toISOString().substring(0, 10),
            dueDate: payload.meta?.dueDate || payload.DueDate || '',
            customerName: payload.customer?.name || payload.ClientName || 'Unnamed Client',
            mobile: payload.customer?.phone || payload.customer?.contact || payload.ClientPhone || '',
            totalAmount: parseFloat(payload.calculations?.grandTotal || payload.GrandTotal || 0) || 0,
            totalBoxes: (payload.rows || []).reduce((sum, r) => sum + (parseFloat(r.boxes) || 0), 0),
            totalUnits: (payload.rows || []).reduce((sum, r) => sum + (parseFloat(r.totalUnits || r.qty) || 0), 0),
            is_stock_deducted: false
          };

          const existingIdx = history.findIndex(h => h.uniqueId === uniqueId || (h.invoiceNumber && h.invoiceNumber === invNum));
          if (existingIdx >= 0) {
            history[existingIdx] = { ...history[existingIdx], ...summary };
          } else {
            history.unshift(summary);
          }
          safeStorage.setItem('invoice_history_cache', JSON.stringify(history));
        }
      } catch (histErr) {
        console.warn('PDF download history save note:', histErr);
      }

      if (typeof advanceToNextInvoiceDraftAfterDownload === 'function') {
        const nextNum = await advanceToNextInvoiceDraftAfterDownload();
        const displayNext = nextNum || $('s-inv-num')?.value || $('p-inv-num')?.textContent || '';
        if (typeof toast === 'function') {
          toast({
            title: 'PDF Downloaded Successfully',
            nextInvoice: displayNext ? displayNext.trim() : '',
            type: 'download-success'
          });
        }
      } else if (typeof toast === 'function') {
        toast({
          title: 'PDF Downloaded Successfully',
          type: 'download-success'
        });
      }

    } catch (err) {
      console.error('PDF generation error:', err);
      if (typeof toast === 'function') {
        toast('PDF generation failed: ' + (err.message || 'Unknown error'), 'error');
      }
    } finally {
      if (btn) {
        btn.innerHTML = '<span class="material-symbols-outlined">download</span> Download PDF';
        btn.disabled = false;
      }
      if (mobBtn) mobBtn.disabled = false;
    }
  }

  // Expose globally
  window.drawA4InvoicePdf = drawA4InvoicePdf;
  window.generateAndDownloadInvoicePDF = generateAndDownloadInvoicePDF;
  window.formatPackSize = formatPackSize;
  window.formatTaxLabel = formatTaxLabel;
  window.buildQrDataUrl = buildQrDataUrl;
  window.getQrDataUrl = getQrDataUrl;

  /**
   * Canonical Invoice PDF Filename Formatter across ERP and Invoice Builder
   *
   * Rules:
   * - Regular invoices:  "Invoice_NN.pdf" (e.g. 1 -> Invoice_01.pdf, 104 -> Invoice_104.pdf)
   * - Dispatch invoices: "INV_NN.pdf"     (e.g. 1 -> INV_01.pdf, INV-02 -> INV_02.pdf, 104 -> INV_104.pdf)
   * - Numbers below 10 padded to at least 2 digits (e.g. "01", "02")
   * - Single .pdf extension
   * - Zero captions, timestamps, or customer names in filename
   */
  function getStandardInvoicePdfFilename(invoiceNumber, isDispatch = false) {
    let raw = String(invoiceNumber || '').trim();
    raw = raw.replace(/\.pdf$/i, '').trim();

    // Strip commercial tax invoice / tax invoice / commercial invoice prefixes
    raw = raw.replace(/^(?:commercial[-_ ]*tax[-_ ]*invoice|commercial[-_ ]*invoice|tax[-_ ]*invoice)[-_ ]*/i, '').trim();

    // If isDispatch is not explicitly boolean false, check if prefix is inv
    let isDisp = isDispatch === true;
    if (isDispatch === null || isDispatch === undefined) {
      isDisp = /^inv[-_ ]/i.test(raw);
    }

    // Strip invoice / inv / dsp prefix
    let numPart = raw.replace(/^(?:invoice|inv|dsp)[-_ ]*/i, '').trim();
    if (!numPart) numPart = '01';

    // Format number part: numbers below 10 are padded to 2 digits; numbers >= 10 retain digits
    if (/^\d+$/.test(numPart)) {
      const val = parseInt(numPart, 10);
      if (!isNaN(val)) {
        numPart = val < 10 ? String(val).padStart(2, '0') : String(val);
      } else {
        numPart = numPart.length < 2 ? numPart.padStart(2, '0') : numPart;
      }
    } else {
      const m = numPart.match(/^(\d+)(.*)$/);
      if (m) {
        const val = parseInt(m[1], 10);
        const digits = (!isNaN(val) && val < 10) ? String(val).padStart(2, '0') : (isNaN(val) ? m[1] : String(val));
        const rest = m[2].replace(/[^a-zA-Z0-9_-]/g, '_');
        numPart = digits + rest;
      } else {
        numPart = numPart.replace(/[^a-zA-Z0-9_-]/g, '_');
      }
    }

    const prefix = isDisp ? 'INV_' : 'Invoice_';
    return `${prefix}${numPart}.pdf`;
  }

  window.getStandardInvoicePdfFilename = getStandardInvoicePdfFilename;

  /**
   * Unified WhatsApp PDF Sharing Service for ERP and Invoice Builder
   * 
   * Strict Guidelines:
   * 1. Prepares vector PDF synchronously in memory to prevent user activation (gesture) expiration.
   * 2. Uses canonical filename: Invoice_NN.pdf or INV_NN.pdf.
   * 3. On supported devices, invokes navigator.share({ files: [pdfFile] }) with ZERO text caption or url.
   *    - Opens native share sheet -> user taps WhatsApp -> WhatsApp opens recipient/contact picker.
   *    - The actual PDF is attached. User can choose ANY recipient or group.
   * 4. NEVER forces a customer chat URL with ?phone=... unless explicitly required.
   * 5. When returning from share sheet: ZERO unwanted instruction popups or duplicate downloads.
   * 6. Unsupported fallback: downloads the PDF, displays a non-intrusive notification, and never fakes attachment.
   */
  async function shareInvoicePdfOnWhatsApp(docOrPayload, options = {}) {
    if (!docOrPayload) {
      const err = new Error('Invoice data is not available for WhatsApp sharing.');
      if (options.onToast) options.onToast(err.message, 'error');
      throw err;
    }

    const payload = docOrPayload;
    const invNum = payload.InvoiceNumber || payload.invoice_no || payload.inv_number || payload.order_no || '01';
    const isDispatch = (options.isDispatch !== undefined)
      ? options.isDispatch
      : !!(payload.dispatchNo || payload.dispatch_no || (typeof window !== 'undefined' && window.currentDispatchNo) || (payload.type === 'dispatch') || String(invNum || '').startsWith('INV-'));

    const filename = options.filename || getStandardInvoicePdfFilename(invNum, isDispatch);

    // 1. Synchronously render vector PDF in memory (pure CPU, ~15ms, preserves user activation)
    const jsPdfLib = (typeof window !== 'undefined' && window.jspdf && window.jspdf.jsPDF)
      ? window.jspdf.jsPDF
      : (typeof jsPDF !== 'undefined' ? jsPDF : null);

    if (!jsPdfLib || typeof drawA4InvoicePdf !== 'function') {
      const err = new Error('PDF generator engine is not ready.');
      if (options.onToast) options.onToast(err.message, 'error');
      throw err;
    }

    const pdf = new jsPdfLib({ orientation: 'portrait', unit: 'mm', format: 'a4' });
    drawA4InvoicePdf(pdf, payload);
    const pdfBlob = pdf.output('blob');

    if (!pdfBlob || pdfBlob.size === 0) {
      const err = new Error('Could not produce invoice PDF.');
      if (options.onToast) options.onToast(err.message, 'error');
      throw err;
    }

    const pdfFile = new File([pdfBlob], filename, { type: 'application/pdf', lastModified: Date.now() });

    // 2. Test native Web Share API Level 2 file sharing capability
    let canShareFile = false;
    if (typeof navigator !== 'undefined' && typeof navigator.share === 'function' && typeof navigator.canShare === 'function') {
      try {
        canShareFile = navigator.canShare({ files: [pdfFile] });
      } catch (_) {
        canShareFile = false;
      }
    }

    // 3. Native File Sharing (Supported on mobile devices, Android, iOS, Windows Share)
    if (canShareFile) {
      try {
        // PDF-ONLY SHARING: Share strictly the actual PDF file without any caption, text, or title
        await navigator.share({
          files: [pdfFile]
        });

        // If user completes share, notify cleanly without any popup modal
        const notify = options.onToast || (typeof window !== 'undefined' && (window.toast || (window.APP && window.APP.showToast)));
        if (typeof notify === 'function') {
          notify(`"${filename}" shared via WhatsApp.`, 'success');
        }
        return { success: true, method: 'native', filename };
      } catch (shareErr) {
        const isCancelled = !shareErr ||
          shareErr.name === 'AbortError' ||
          shareErr.name === 'NotAllowedError' ||
          String(shareErr).toLowerCase().includes('cancel') ||
          String(shareErr).toLowerCase().includes('abort') ||
          String(shareErr).toLowerCase().includes('dismiss');

        if (isCancelled) {
          console.log('Native share sheet dismissed by user.');
          return { success: false, cancelled: true };
        }
        console.warn('Native sharing encountered an issue, falling back to download:', shareErr);
      }
    }

    // 4. Honest Fallback for Unsupported Browsers / Insecure HTTP Contexts:
    const isMobile = ((typeof navigator !== 'undefined') && /Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent)) ||
                     ((typeof window !== 'undefined') && (
                       window.innerWidth <= 768 ||
                       (window.matchMedia && window.matchMedia('(max-width: 768px)').matches)
                     ));

    const isSecure = typeof window !== 'undefined' && window.isSecureContext;

    // On mobile devices: Do NOT trigger a browser download dialog when user clicked "Send on WhatsApp".
    // The user clicked "Send on WhatsApp", not "Download PDF". Inform the user clearly why native share
    // is unavailable (requires HTTPS) and direct them to open via HTTPS or use the explicit "Download PDF" button.
    if (isMobile) {
      let fallbackMsg = `Direct WhatsApp sharing is not supported in this browser. Please use the "Download PDF" button to download and attach it manually.`;
      if (!isSecure) {
        fallbackMsg = `Direct WhatsApp sharing requires a secure (HTTPS) connection. Please open the site via HTTPS, or use "Download PDF" to attach manually.`;
      }

      const notify = options.onToast || (typeof window !== 'undefined' && (window.toast || (window.APP && window.APP.showToast)));
      if (typeof notify === 'function') {
        notify(fallbackMsg, 'warning', 8000);
      }
      return { success: false, method: 'unsupported_insecure', filename };
    }

    // Desktop only: on unsupported desktop browsers, download PDF and open WhatsApp Web
    const saveBlobFn = (typeof window !== 'undefined' && window.savePdfBlob)
      ? window.savePdfBlob
      : (typeof savePdfBlob === 'function' ? savePdfBlob : null);

    if (saveBlobFn) {
      saveBlobFn(pdf, filename);
    } else {
      pdf.save(filename);
    }

    if (typeof window !== 'undefined') {
      window._lastDownloadedInvoicePdf = filename;
      if (typeof window._onPdfSaved === 'function') {
        try { window._onPdfSaved(filename); } catch (_) {}
      }
    }

    const waUrl = 'https://web.whatsapp.com';
    if (typeof window !== 'undefined') {
      window._lastOpenedWhatsAppUrl = waUrl;
      if (Array.isArray(window._openedUrls)) window._openedUrls.push(waUrl);
      if (Array.isArray(window._erpOpenedUrls)) window._erpOpenedUrls.push(waUrl);
    }
    try {
      window.open(waUrl, '_blank');
    } catch (_) {}

    const notify = options.onToast || (typeof window !== 'undefined' && (window.toast || (window.APP && window.APP.showToast)));
    if (typeof notify === 'function') {
      notify(`Downloaded "${filename}". Opening WhatsApp Web — attach the file manually.`, 'info', 7000);
    }

    return { success: true, method: 'download_fallback', filename };
  }

  window.shareInvoicePdfOnWhatsApp = shareInvoicePdfOnWhatsApp;
  function getStateCodeFromName(stateName) {
    if (!stateName) return '';
    const clean = String(stateName).trim().toLowerCase();
    for (const [code, name] of Object.entries(GST_STATE_MAP)) {
      if (name.toLowerCase() === clean) return code;
    }
    return '';
  }

  window.getStateCodeFromName = getStateCodeFromName;
  window.INDIAN_STATES = INDIAN_STATES;
  window.GST_STATE_MAP = GST_STATE_MAP;
  window.resolveClientAddressAndState = resolveClientAddressAndState;

})(window);
